251	func skipRest(dec *json.Decoder, tok json.Token) error {
252		delim, ok := tok.(json.Delim)
253		if !ok {
254			return nil // scalar, fully consumed already
255		}
256		var closer json.Delim
257		switch delim {
258		case '{':
259			closer = '}'
260			for dec.More() {
261				if _, err := scanKey(dec); err != nil {
262					return err
263				}
264				if err := skipValue(dec); err != nil {
265					return err
266				}
267			}
268		case '[':
269			closer = ']'
270			for dec.More() {
271				if err := skipValue(dec); err != nil {
272					return err
273				}
274			}
275		default:
276			return errAbortScan
277		}
278		tok, err := scanToken(dec)
279		if err != nil {
280			return err
281		}
282		if end, ok := tok.(json.Delim); !ok || end != closer {
283			return errAbortScan
284		}
285		return nil
286	}
